@layer components {
  /* ProfileCard component tokens */
  :root {
    --shelf-profile-card-bgColor-base: var(--shelf-bgColor-surface);
    --shelf-profile-card-borderColor-base: var(--shelf-borderColor-default);
    --shelf-profile-card-fgColor-title: var(--shelf-fgColor-default);
    --shelf-profile-card-fgColor-subtitle: var(--shelf-fgColor-muted);
    --shelf-profile-card-borderWidth: var(--shelf-borderWidth-thin);
    --shelf-profile-card-spacing: var(--shelf-spacing-md);
    --shelf-profile-card-radius: var(--shelf-radius-md);
    --shelf-profile-card-skeleton-bgColor: var(--shelf-bgColor-skeleton);
    --shelf-profile-card-skeleton-shimmerColor: var(--shelf-bgColor-skeleton-shimmer);
  }

  [data-theme="dark"],
  @media (prefers-color-scheme: dark) {
    :root {
      --shelf-profile-card-bgColor-base: var(--shelf-bgColor-surface);
      --shelf-profile-card-borderColor-base: var(--shelf-borderColor-default);
      --shelf-profile-card-fgColor-title: var(--shelf-fgColor-default);
      --shelf-profile-card-fgColor-subtitle: var(--shelf-fgColor-muted);
      --shelf-profile-card-skeleton-bgColor: var(--shelf-bgColor-skeleton);
      --shelf-profile-card-skeleton-shimmerColor: var(--shelf-bgColor-skeleton-shimmer);
    }
  }

  .profile-card {
    background-color: var(--shelf-profile-card-bgColor-base);
    border: var(--shelf-profile-card-borderWidth) solid var(--shelf-profile-card-borderColor-base);
    border-radius: var(--shelf-profile-card-radius);
    padding: var(--shelf-profile-card-spacing);
  }

  .profile-card-title {
    color: var(--shelf-profile-card-fgColor-title);
    font-size: var(--shelf-fontSize-lg);
    font-weight: var(--shelf-fontWeight-semibold);
  }

  .profile-card-subtitle {
    color: var(--shelf-profile-card-fgColor-subtitle);
    font-size: var(--shelf-fontSize-sm);
  }

  /* Skeleton variant */
  .profile-card--skeleton .profile-card-title,
  .profile-card--skeleton .profile-card-subtitle {
    background-color: var(--shelf-profile-card-skeleton-bgColor);
    border-radius: var(--shelf-radius-sm);
    color: transparent;
    overflow: hidden;
    position: relative;
  }

  .profile-card--skeleton .profile-card-title {
    width: 100%;
  }

  .profile-card--skeleton .profile-card-subtitle {
    width: 60%;
  }

  .profile-card--skeleton .profile-card-title::after,
  .profile-card--skeleton .profile-card-subtitle::after {
    animation: profile-card-shimmer var(--shelf-duration-slow) var(--shelf-easing-linear) infinite;
    background: linear-gradient(
      90deg,
      transparent 0%,
      var(--shelf-profile-card-skeleton-shimmerColor) 50%,
      transparent 100%
    );
    content: "";
    inset: 0;
    position: absolute;
    transform: translateX(-100%);
  }

  @keyframes profile-card-shimmer {
    to {
      transform: translateX(100%);
    }
  }
}
